uint16_t input_pressed(const GameState *g)
{
    if (!peeking)
        state_host_game_access(g, 16);
    const VarsHost *h = state_host_vars_const(g);
    if (!peeking)
        vars_host_check(h, 0x7E00F0u, 2u, 1u);
    return h->core.input_pressed;
}
