uint16_t input_mapped(const GameState *g, unsigned i)
{
    IN_RANGE(g, 0, "input_mapped", "count", i, 3u);
    if (i >= 3u) { return r16(g, 0x7E00F6u + (uint32_t)i * 0x02u); }
    if (!peeking)
        state_host_game_access(g, 16);
    const VarsHost *h = state_host_vars_const(g);
    if (!peeking)
        vars_host_check(h, 0x7E00F6u + (uint32_t)i * 0x02u, 2u, 4u);
    return h->core.input_mapped[i];
}
void set_input_mapped(GameState *g, unsigned i, uint16_t v)
{
    IN_RANGE(g, 0, "set_input_mapped", "count", i, 3u);
    if (i >= 3u) { w16(g, 0x7E00F6u + (uint32_t)i * 0x02u, v); return; }
    if (!peeking)
        state_host_game_access(g, 16);
    VarsHost *h = state_host_vars(g);
    h->core.input_mapped[i] = v;
    vars_host_claim(h, 0x7E00F6u + (uint32_t)i * 0x02u, 2u, 4u);
}
