{
    IN_RANGE(g, 828, "battle_map_buffer", "count", i, 6144u);
    if (i >= 6144u) { return r16(g, 0x7ED000u + (uint32_t)i * 0x02u); }
    if (!peeking)
        state_host_game_access(g, 16);
    const VarsHost *h = state_host_vars_const(g);
    if (!peeking)
        vars_host_check(h, 0x7ED000u + (uint32_t)i * 0x02u, 2u, 1876u);
    return h->battle.battle_map_buffer[i];
}
